#include <vector>
using namespace std;

class Solution {
public:
    int countPaths(vector<vector<int>>& grid) {
        const int MOD = 1000000007;
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> memo(m, vector<int>(n, -1));
        auto dfs = [&](auto& self, int r, int c) -> int {
            if (memo[r][c] != -1) return memo[r][c];
            long long res = 1;
            int dr[] = {0, 1}, dc[] = {1, 0};
            for (int i = 0; i < 2; i++) {
                int nr = r + dr[i], nc = c + dc[i];
                if (nr < m && nc < n && grid[nr][nc] > grid[r][c]) {
                    res = (res + self(self, nr, nc)) % MOD;
                }
            }
            return memo[r][c] = res;
        };
        long long total = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                total = (total + dfs(dfs, r, c)) % MOD;
            }
        }
        return total;
    }
};

class Solution {
    private static final int MOD = 1_000_000_007;
    private int[][] memo;

    public int countPaths(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        memo = new int[m][n];
        long total = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                total = (total + dfs(grid, r, c, m, n)) % MOD;
            }
        }
        return (int)total;
    }

    private int dfs(int[][] grid, int r, int c, int m, int n) {
        if (memo[r][c] != 0) return memo[r][c];
        long res = 1;
        int[] dr = {0, 1}, dc = {1, 0};
        for (int i = 0; i < 2; i++) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr < m && nc < n && grid[nr][nc] > grid[r][c]) {
                res = (res + dfs(grid, nr, nc, m, n)) % MOD;
            }
        }
        return memo[r][c] = (int)res;
    }
}

var countPaths = function(grid) {
    const MOD = 1000000007;
    const m = grid.length, n = grid[0].length;
    const memo = Array.from({ length: m }, () => new Int32Array(n).fill(-1));
    function dfs(r, c) {
        if (memo[r][c] !== -1) return memo[r][c];
        let res = 1;
        const dirs = [[0, 1], [1, 0]];
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr < m && nc < n && grid[nr][nc] > grid[r][c]) {
                res = (res + dfs(nr, nc)) % MOD;
            }
        }
        return memo[r][c] = res;
    }
    let total = 0;
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            total = (total + dfs(r, c)) % MOD;
        }
    }
    return total;
};
